#include <stdio.h>
#include <string.h>

#define MAX_SIZE 1000

// 一个以顺序储存结构存储整数值的完全二叉树序列
int nums[MAX_SIZE];
int nums_size = 0;

// 非叶子节点后序遍历序列
int non_leafs[MAX_SIZE];
int non_leafs_size = 0;

// 记录题解
char res[10000];

void dfs(int root);

int main() {
    while (scanf("%d", &nums[nums_size++])) {
        if (getchar() != ' ') break;
    }

    if (nums_size == 1) {
        // 只有一个节点时，直接输出
        printf("%d\n", nums[0]);
    } else {
        // 按照后序遍历规则，递归完全二叉树
        dfs(0);

        // 打印非叶子节点的后序遍历
        for (int i = 0; i < non_leafs_size; i++) {
            char tmp[100];
            sprintf(tmp, "%d", non_leafs[i]);

            strcat(res, tmp);
            strcat(res, " ");
        }

        // 按照前面拼接逻辑，res末尾会多拼接一个空格
        res[strlen(res) - 1] = '\0';

        puts(res);
    }

    return 0;
}

void dfs(int root) {
    int left = root * 2 + 1;
    int right = root * 2 + 2;

    // 左：如果左孩子不为空，则说明第i个元素不是叶子，因此继续递归其左孩子，即将左孩子当成新的根来递归
    if (nums_size > left) {
        dfs(left);
        // 右：如果右孩子也不为空，则根据后序遍历原则，还要对右孩子进行递归
        if (nums_size > right) dfs(right);
        // 根
        non_leafs[non_leafs_size++] = nums[root];
    }
}
